using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RepairWithEffectCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/RepairWithEffectCustomDescription", order = 0)]
public class RepairWithEffectCustomDescription : RepairCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		RepairWithEffectAction repairWithEffectAction = battleAction as RepairWithEffectAction;
		string arg = Smart.Format(base.localizationManager.GetLocalizedString("ThatSentinelEffect"), amountModified, repairWithEffectAction.Effect.GetEffectName()).LowercaseFirst();
		return GetRepairASentinelLocalizedString() + "\n" + Smart.Format(GetIfYouDoLocalizedString(), arg);
	}
}
